// lesson02 ch04: コメント
package main

import "fmt"

// main の直前のコメントは「この関数の説明」を書く場所という慣習があります
func main() {
	// これは 1 行コメントです。この行は実行されません
	fmt.Println("コメントは出力されません")

	/*
	   これは複数行コメントです。
	   まとまった説明や、一時的にコードを無効にしたいときに使います。
	*/
	fmt.Println("ここは実行されます") // 行の後ろにも書けます
}

