// lesson02 ch04 解答
package main

import "fmt"

func main() {
	fmt.Println("おはよう")
	// 行頭に // を付けるとその行はコンパイル対象から外れます。
	// 削除と違って元に戻すのが簡単なので、
	// 「一時的に消したい」ときはコメントアウトを使います。
	// fmt.Println("こんにちは")
	fmt.Println("こんばんは")
}
